CREATE TABLE capital_source_matches (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL, institution_id uuid NOT NULL REFERENCES institutional_profiles(id) ON DELETE CASCADE, source_profile_id uuid NOT NULL REFERENCES capital_source_profiles(id) ON DELETE CASCADE, fit_score integer NOT NULL DEFAULT 0, fit_state text NOT NULL DEFAULT 'not_assessed', rationale text, strengths jsonb NOT NULL DEFAULT '[]'::jsonb, gaps jsonb NOT NULL DEFAULT '[]'::jsonb, next_actions jsonb NOT NULL DEFAULT '[]'::jsonb, assessed_at timestamptz NOT NULL DEFAULT now(), UNIQUE(project_id,institution_id));